.consent-panel{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);width:calc(100% - 40px);max-width:720px;padding:22px;background:#fff;border:1px solid #cad6ce;border-radius:14px;box-shadow:0 10px 40px #0003;z-index:100;color:#17332f}
.consent-panel p{font-size:14px;line-height:1.6;margin:0 0 12px}
.consent-actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center}
.consent-actions button{font-size:14px;padding:12px 20px}.consent-actions a{color:inherit;font-size:13px}
.footer-button{font-size:12px;padding:0;background:transparent;color:inherit;text-decoration:underline;font-weight:400}
:root[data-theme="dark"] .consent-panel{background:#192620;color:#e0eee6;border-color:#476152}
